import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";import{A as i,O as a,k as o}from"./chunks/assets.DjpLsfX1.js";var s=JSON.parse(`{"title":"Product Props Management Guide (Properties Meta)","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/05-props.md","filePath":"02-consumer/05-props.md"}`),c={name:`02-consumer/05-props.md`};function l(n,s,c,l,u,d){return r(),t(`div`,null,[...s[0]||=[e(`<h1 id="product-props-management-guide-properties-meta" tabindex="-1">Product Props Management Guide (Properties Meta) <a class="header-anchor" href="#product-props-management-guide-properties-meta" aria-label="Permalink to “Product Props Management Guide (Properties Meta)”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>The <strong>Properties Meta</strong> section is used to define and manage product props in the store. These props can be defined for any type of store, from clothing and digital goods stores to stores selling physical and virtual products.</p><p>The purpose of this section is to provide a dynamic structure for product specifications. Instead of defining fixed fields for each product type, the required props are defined through the admin panel, and the system uses them in different sections.</p><p>The defined props have three main uses:</p><ol><li><strong>Better search:</strong> Enable searching and filtering products based on their specifications.</li><li><strong>Inventory and price management:</strong> Distinguish between the different sellable variations of a product based on combinations of props, while managing quantities and price differences.</li><li><strong>Product comparison:</strong> Display and compare corresponding product specifications to help users make better choices.</li></ol><h3 id="dynamic-structure" tabindex="-1">Dynamic Structure <a class="header-anchor" href="#dynamic-structure" aria-label="Permalink to “Dynamic Structure”">​</a></h3><p>The process for using props is dynamic. The store manager defines the required props and settings in the Properties Meta section. The system then uses these definitions to display the relevant props in product creation and editing forms, and makes searchable props available in product filters.</p><p>This structure also makes it possible to use corresponding product specifications for comparison.</p><p>Therefore, there is no need to design a dedicated form or a separate filter for every new prop. Simply define a prop that suits the store&#39;s needs and link it to the relevant categories.</p><h2 id="_1-defining-and-editing-a-prop" tabindex="-1">1. Defining and Editing a Prop <a class="header-anchor" href="#_1-defining-and-editing-a-prop" aria-label="Permalink to “1. Defining and Editing a Prop”">​</a></h2><p>In the <strong>Properties Meta</strong> section, you can create and manage the props required by the store.</p><p><img src="`+i+`" alt="Prop management page" width="1907" height="825"></p><p>Each prop includes general information, related categories, settings for its options, and, if needed, an icon.</p><h3 id="general-prop-information" tabindex="-1">General Prop Information <a class="header-anchor" href="#general-prop-information" aria-label="Permalink to “General Prop Information”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>Name</code></td><td>The technical name used to identify the prop in the system. It must be in Latin characters and contain no spaces.</td></tr><tr><td><code>Label</code></td><td>The user-facing title of the prop, such as <code>Color</code>, <code>Size</code>, or <code>Material</code>.</td></tr><tr><td><code>Width</code></td><td>The CSS class used to determine the prop&#39;s width in the product specifications form.</td></tr><tr><td><code>Required</code></td><td>Specifies whether the prop must be completed when creating a product.</td></tr><tr><td><code>Searchable</code></td><td>Specifies whether the prop can be used for product search and filtering.</td></tr><tr><td><code>Unit</code></td><td>The unit displayed for the prop&#39;s value, such as <code>kg</code>, <code>cm</code>, or <code>Gig</code>, as appropriate for the product type.</td></tr><tr><td><code>Type</code></td><td>Specifies the input type and how the prop&#39;s value is collected.</td></tr><tr><td><code>Is effective price?</code></td><td>Specifies whether the prop&#39;s value affects the product pricing mechanism.</td></tr></tbody></table><p><strong>Note:</strong> The <code>Name</code> value is a technical identifier and differs from the user-facing <code>Label</code>. For example, the technical name of a prop could be <code>material</code>, while its user-facing title is <code>Material</code>.</p><h3 id="prop-types-type" tabindex="-1">Prop Types (Type) <a class="header-anchor" href="#prop-types-type" aria-label="Permalink to “Prop Types (Type)”">​</a></h3><p>The prop type determines how its value is entered and displayed in the user interface.</p><table tabindex="0"><thead><tr><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>text</code></td><td>Collects a text value, such as fabric type or warranty name</td></tr><tr><td><code>number</code></td><td>Collects a numeric value, such as weight or dimensions</td></tr><tr><td><code>checkbox</code></td><td>Records a selected or unselected state, such as whether an item is waterproof</td></tr><tr><td><code>color</code></td><td>Selects a color from a list of color options</td></tr><tr><td><code>select</code></td><td>Selects one option from a list</td></tr><tr><td><code>singlemulti</code></td><td>Selects one value for a product, while allowing multiple values to be selected in a filter</td></tr><tr><td><code>multi</code></td><td>Selects multiple options for a prop</td></tr><tr><td><code>date</code></td><td>Collects a date</td></tr><tr><td><code>time</code></td><td>Collects a time</td></tr></tbody></table><p>Choose an appropriate type based on the nature of the prop and its use in the store.</p><p>For example:</p><ul><li>In a clothing store, you can define props such as color, size, and fabric type.</li><li>In a digital goods store, you can define memory capacity, weight, and connection type.</li><li>In a virtual products store, you can define props such as license type, validity period, or product format.</li></ul><p>These are only examples of how props can be used; the system is not limited to these categories.</p><h3 id="prop-width-width" tabindex="-1">Prop Width (Width) <a class="header-anchor" href="#prop-width-width" aria-label="Permalink to “Prop Width (Width)”">​</a></h3><p>The <code>Width</code> field determines how the prop is positioned in the product specifications form.</p><p>For example, the <code>col-md-6</code> class typically occupies half the row width, while the <code>col-md-12</code> class occupies the full row width in a twelve-column Bootstrap grid.</p><h3 id="required-prop-required" tabindex="-1">Required Prop (Required) <a class="header-anchor" href="#required-prop-required" aria-label="Permalink to “Required Prop (Required)”">​</a></h3><p>This option specifies whether the prop must be completed when creating a product.</p><p>For example, if specifying the size is required for a clothing product, you can set the size prop as required.</p><h3 id="searchability-searchable" tabindex="-1">Searchability (Searchable) <a class="header-anchor" href="#searchability-searchable" aria-label="Permalink to “Searchability (Searchable)”">​</a></h3><p>When this option is enabled, the prop becomes available for product search and filtering.</p><p>The system generates the relevant filters based on the defined props and their settings. Therefore, there is no need to manually design a separate filter for each prop.</p><h3 id="price-effective-prop-is-effective-price" tabindex="-1">Price-Effective Prop (Is effective price?) <a class="header-anchor" href="#price-effective-prop-is-effective-price" aria-label="Permalink to “Price-Effective Prop (Is effective price?)”">​</a></h3><p>This option specifies whether the prop&#39;s value plays a role in determining the product price.</p><p>For example, differences in material, size, capacity, or license type may affect the price of different variations of a product.</p><p>Enabling this option does not, by itself, create a price or inventory. Information about sellable variations and their quantities and prices must also be entered as part of product management.</p><h2 id="_2-linking-props-to-categories-categories" tabindex="-1">2. Linking Props to Categories (Categories) <a class="header-anchor" href="#_2-linking-props-to-categories-categories" aria-label="Permalink to “2. Linking Props to Categories (Categories)”">​</a></h2><p>The <strong>Categories</strong> section specifies which categories&#39; products can use each prop.</p><p><img src="`+i+`" alt="Selecting categories related to a prop" width="1907" height="825"></p><p>For example, the size prop can be linked to the clothing category, and the validity period prop can be linked to the virtual products category.</p><p>To link a prop to categories:</p><ol><li>Select the desired categories from the list.</li><li>Review your selections based on the store&#39;s category structure.</li><li>Save your changes after completing the other settings.</li></ol><p>Each prop can be linked to multiple categories, and each category can use multiple props.</p><p>When creating or editing a product, the system uses the props associated with the product&#39;s primary category to determine which specifications can be entered.</p><h2 id="_3-defining-prop-options" tabindex="-1">3. Defining Prop Options <a class="header-anchor" href="#_3-defining-prop-options" aria-label="Permalink to “3. Defining Prop Options”">​</a></h2><p>Some props require a set of defined options. In such cases, the options are defined in the section for that prop.</p><p><img src="`+i+`" alt="Managing prop options" width="1907" height="825"></p><p>Each option has two main values:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>Title</code></td><td>The option title</td></tr><tr><td><code>Value</code></td><td>The technical value or the value used for the option in the system</td></tr></tbody></table><p>For example, the size prop can have options such as <code>S</code>, <code>M</code>, <code>L</code>, and <code>XL</code>. The color prop can include different colors along with their corresponding color values.</p><p>To add an option, enter its information. To remove an existing option, use the delete control on its row.</p><p>When you finish editing, click the <code>Save</code> button to save your changes.</p><h3 id="difference-between-select-singlemulti-and-multi" tabindex="-1">Difference Between Select, Singlemulti, and Multi <a class="header-anchor" href="#difference-between-select-singlemulti-and-multi" aria-label="Permalink to “Difference Between Select, Singlemulti, and Multi”">​</a></h3><ul><li><strong>Select:</strong> Selects one option from a list.</li><li><strong>Singlemulti:</strong> Selects one value for a product, while allowing multiple options to be selected in a filter.</li><li><strong>Multi:</strong> Selects multiple options for the value of a prop.</li></ul><p>The <code>color</code> type is also used to select from color options.</p><p>Choose the prop type based on the store&#39;s needs so that its input and filter behavior are appropriate.</p><h2 id="_4-selecting-a-prop-icon-icon" tabindex="-1">4. Selecting a Prop Icon (Icon) <a class="header-anchor" href="#_4-selecting-a-prop-icon-icon" aria-label="Permalink to “4. Selecting a Prop Icon (Icon)”">​</a></h2><p>The <strong>Icon</strong> section is used to select an icon associated with a prop.</p><p><img src="`+i+`" alt="Prop icon selection section" width="1907" height="825"></p><p>An icon can help visually identify a prop. For example, you can choose a suitable icon for props related to weight, color, or other specifications.</p><p>Whether the icon is displayed in different sections depends on the user interface that uses the prop.</p><h2 id="_5-using-props-to-enter-specifications-and-manage-inventory" tabindex="-1">5. Using Props to Enter Specifications and Manage Inventory <a class="header-anchor" href="#_5-using-props-to-enter-specifications-and-manage-inventory" aria-label="Permalink to “5. Using Props to Enter Specifications and Manage Inventory”">​</a></h2><p>After defining props and linking them to categories, the system makes the relevant props available in the product creation or editing form. This depends on the product&#39;s primary category; secondary categories have no effect.</p><p><img src="`+o+`" alt="Example of using props in the product specifications and inventory form" width="1907" height="725"></p><p>This form is generated based on the defined props. Therefore, its layout and input fields depend on the product type and the settings of its related props.</p><p>In the section for managing a product&#39;s sellable variations, you can enter different combinations of props along with information such as quantity and price.</p><p>For example, a clothing store may offer a product in different sizes and colors, with each combination having a different inventory quantity and price. A virtual products store may define different product variations based on license type or validity period.</p><p>This structure helps manage inventory and price information for different variations of a product without necessarily defining a separate base product for every combination.</p><p><strong>Note:</strong> The exact way props affect price and inventory depends on the prop settings and the logic used to manage a product&#39;s sellable variations.</p><h2 id="_6-displaying-props-in-product-filters" tabindex="-1">6. Displaying Props in Product Filters <a class="header-anchor" href="#_6-displaying-props-in-product-filters" aria-label="Permalink to “6. Displaying Props in Product Filters”">​</a></h2><p>Props with the <code>Searchable</code> option enabled can be made available automatically in product filters.</p><p><img src="`+a+`" alt="Example of displaying props in product filters" width="389" height="611"></p><p>The prop type determines how its filter is displayed, for example, as a single-option selection, a multiple-option selection, or a toggle.</p><p>Users can select the values they want to narrow product results based on product specifications.</p><p>This process is dynamic: when new props are defined and linked to the relevant categories, the system can generate appropriate filters based on the prop settings. There is no need to define each filter manually.</p><h2 id="_7-comparing-products" tabindex="-1">7. Comparing Products <a class="header-anchor" href="#_7-comparing-products" aria-label="Permalink to “7. Comparing Products”">​</a></h2><p>Another use of the props structure is to enable comparisons between corresponding product specifications.</p><p>By defining standard props and using them for related products, product information is structured, and corresponding specifications can be reviewed side by side.</p><p>For example, in a clothing store, you can compare the size, material, and color of products. In a digital goods store, capacity, weight, and other specifications can also be compared.</p><p>Product comparison depends on defining appropriate props and entering compatible values for related products.</p><h2 id="_8-saving-changes" tabindex="-1">8. Saving Changes <a class="header-anchor" href="#_8-saving-changes" aria-label="Permalink to “8. Saving Changes”">​</a></h2><p>After defining a prop, selecting categories, configuring options, and choosing an icon, save your changes using the save button for that page.</p><p>Once saved, the system can use the props according to their settings in product creation forms, filters, and other related sections.</p><h2 id="_9-recommended-procedure-for-defining-a-new-prop" tabindex="-1">9. Recommended Procedure for Defining a New Prop <a class="header-anchor" href="#_9-recommended-procedure-for-defining-a-new-prop" aria-label="Permalink to “9. Recommended Procedure for Defining a New Prop”">​</a></h2><p>To define a new prop in the store:</p><ol><li>Go to the <strong>Properties Meta</strong> section.</li><li>Create a new prop.</li><li>Specify its technical name and user-facing title.</li><li>Set its input type, width, and whether it is required.</li><li>If it should be available in filters, enable the <code>Searchable</code> option.</li><li>If the prop should affect the price, configure the relevant price option.</li><li>Select the related categories.</li><li>If needed, define the prop&#39;s options.</li><li>Choose an appropriate icon.</li><li>Save your changes.</li><li>Check how it works in the product creation form, filters, and other related sections.</li></ol><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h2><ul><li>Props can be defined for all types of stores and products; they are not limited to a specific product group.</li><li>Product specifications forms and filters are generated dynamically based on the props and their settings.</li><li><code>Searchable</code> is used for search and filtering; <code>priceable</code> specifies the prop&#39;s role in determining the price.</li><li>Linking a prop to a category specifies which group of products can use that prop.</li><li>Defining corresponding props and entering compatible values is important for accurate product comparisons.</li><li>After creating or editing a prop, check its behavior in the product creation form and related sections.</li><li>Props can be reordered.</li></ul>`,89)]])}var u=n(c,[[`render`,l]]);export{s as __pageData,u as default};